package com.campusradar.knowledge;

import com.campusradar.common.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static com.campusradar.common.SqlRows.map;

@Service
public class KnowledgeService {
    private final SqlRows r; private final OwnerTransactions tx; private final ContractInputs inputs;
    private static final Set<String> TAGS=Set.of("tags"), COMPANY_JSON=Set.of("cities","tags");
    private static final String CHAPTER="id,version,created_at,updated_at,parent_id,slug,title,direction,sort_order,body_md,content_version,status";
    private static final String COMPANY="id,version,created_at,updated_at,slug,name,logo_url,industry,size_band,cities,tags,description_md,verified_at";
    private static final String EXP="id,version,created_at,updated_at,company_id,title,summary,body_md,role,round_type,occurred_on,tags,author_id,status,source_url,content_mode,license_note";
    private static final String QUESTION="id,version,created_at,updated_at,title,prompt_md,answer_md,role,difficulty,tags,chapter_id,status";
    public record Page(List<Map<String,Object>> data,long total) {}
    public KnowledgeService(SqlRows r,OwnerTransactions tx,ContractInputs inputs){this.r=r;this.tx=tx;this.inputs=inputs;}
    private static ApiProblem missing(){return new ApiProblem(404,"NOT_FOUND","内容不存在或不可访问。");}
    public static void paging(int page,int size){if(page<1||page>500||size<1||size>100)throw new ApiProblem(422,"VALIDATION_ERROR","分页参数无效。");}
    public static String query(String q){q=q==null?"":q.trim();if(q.length()>100||q.length()==1)throw new ApiProblem(422,q.length()==1?"Q_TOO_SHORT":"VALIDATION_ERROR","关键词须为2至100个字符。");return q;}
    private static void version(Object actual,Object expected){if(!(expected instanceof Number n)||((Number)actual).intValue()!=n.intValue())throw new ApiProblem(409,"VERSION_CONFLICT","内容已更新，请重新载入后保存。草稿仍可保留。");}
    public Page companies(String q,int page,int size){paging(page,size);q=query(q);var p=map("q","%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%","offset",(page-1)*size,"size",size);String where=q.isEmpty()?"":" WHERE name LIKE :q ESCAPE '!'";return new Page(r.query("SELECT "+COMPANY+" FROM companies"+where+" ORDER BY name,id LIMIT :size OFFSET :offset",p,COMPANY_JSON,Set.of()),r.db.queryForObject("SELECT COUNT(*) FROM companies"+where,p,Long.class));}
    public Map<String,Object> company(String id){return r.one("SELECT "+COMPANY+" FROM companies WHERE id=:id",map("id",id),COMPANY_JSON,Set.of());}
    public Map<String,Object> companyBySlug(String slug){return r.one("SELECT "+COMPANY+" FROM companies WHERE slug=:s",map("s",slug),COMPANY_JSON,Set.of());}
    public List<Map<String,Object>> chapters(String direction,String q){q=query(q);var p=map("direction",direction,"q","%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%");String where=" WHERE status='PUBLISHED'";if(direction!=null&&!direction.isBlank()){if(direction.length()>40)throw new ApiProblem(422,"VALIDATION_ERROR","方向过长。");where+=" AND direction=:direction";}if(!q.isEmpty())where+=" AND title LIKE :q ESCAPE '!'";return r.query("SELECT "+CHAPTER+" FROM chapters"+where+" ORDER BY direction,sort_order,id LIMIT 1000",p);}
    public Map<String,Object> chapter(String slug){return r.one("SELECT "+CHAPTER+" FROM chapters WHERE slug=:s AND status='PUBLISHED'",map("s",slug),Set.of(),Set.of());}
    private Map<String,Object> published(String table,String fields,String id,Set<String> json){return r.one("SELECT "+fields+" FROM "+table+" WHERE id=:id AND status='PUBLISHED'",map("id",id),json,Set.of());}
    public Map<String,Object> chapterProgress(String u,String id){published("chapters",CHAPTER,id,Set.of());return r.one("SELECT id,version,created_at,updated_at,chapter_id,completed,note,chapter_version FROM chapter_progress WHERE user_id=:u AND chapter_id=:id",map("u",u,"id",id),Set.of(),Set.of("completed"));}
    @SuppressWarnings("unchecked") public Map<String,Object> putChapterProgress(String u,String id,Map<String,Object> body){inputs.validate("ChapterProgressPut",body);return (Map<String,Object>)tx.write(u,"PUT","/handbook/progress/"+id,null,body,200,true,()->{
        var chapter=published("chapters",CHAPTER,id,Set.of());if(((Number)chapter.get("contentVersion")).intValue()!=((Number)body.get("chapterVersion")).intValue())throw new ApiProblem(409,"VERSION_CONFLICT","章节正文已更新，请重新载入。");
        var p=map("u",u,"chapter",id,"id",UUID.randomUUID().toString(),"version",body.get("version"),"completed",body.get("completed"),"note",body.get("note"),"cv",body.get("chapterVersion"));
        long count=r.db.queryForObject("SELECT COUNT(*) FROM chapter_progress WHERE user_id=:u AND chapter_id=:chapter",p,Long.class);
        if(count==0){version(0,body.get("version"));r.db.update("INSERT INTO chapter_progress(id,user_id,chapter_id,completed,note,chapter_version) VALUES(:id,:u,:chapter,:completed,:note,:cv)",p);}else {var old=chapterProgress(u,id);version(old.get("version"),body.get("version"));r.db.update("UPDATE chapter_progress SET completed=:completed,note=:note,chapter_version=:cv,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND chapter_id=:chapter AND version=:version",p);}return chapterProgress(u,id);
    });}
    private Map<String,Object> withCompanies(Map<String,Object> question){question.put("companyIds",r.db.queryForList("SELECT qc.company_id FROM question_companies qc WHERE qc.question_id=:id ORDER BY qc.company_id",map("id",question.get("id")),String.class));return question;}
    public Page questions(String q,String role,String difficulty,String company,int page,int size){paging(page,size);q=query(q);if(difficulty!=null&&!Set.of("EASY","MEDIUM","HARD").contains(difficulty))throw new ApiProblem(422,"VALIDATION_ERROR","难度无效。");var p=map("q",q,"role",role,"difficulty",difficulty,"company",company,"size",size,"offset",(page-1)*size);String where=" WHERE status='PUBLISHED'";if(!q.isEmpty())where+=" AND MATCH(title,prompt_md) AGAINST (:q IN NATURAL LANGUAGE MODE)";if(role!=null&&!role.isBlank())where+=" AND role=:role";if(difficulty!=null)where+=" AND difficulty=:difficulty";if(company!=null&&!company.isBlank())where+=" AND EXISTS (SELECT 1 FROM question_companies qc WHERE qc.question_id=questions.id AND qc.company_id=:company)";var rows=r.query("SELECT "+QUESTION+" FROM questions"+where+" ORDER BY updated_at DESC,id LIMIT :size OFFSET :offset",p,TAGS,Set.of());rows.forEach(this::withCompanies);return new Page(rows,r.db.queryForObject("SELECT COUNT(*) FROM questions"+where,p,Long.class));}
    public Map<String,Object> question(String id){return withCompanies(published("questions",QUESTION,id,TAGS));}
    public Map<String,Object> questionProgress(String u,String id){question(id);return r.one("SELECT id,version,created_at,updated_at,question_id,mastery,is_wrong,note FROM question_progress WHERE user_id=:u AND question_id=:id",map("u",u,"id",id),Set.of(),Set.of("is_wrong"));}
    public Object putQuestionProgress(String u,String id,Map<String,Object> body){inputs.validate("QuestionProgressPut",body);return tx.write(u,"PUT","/questions/"+id+"/progress",null,body,200,true,()->{
        question(id);var p=map("u",u,"q",id,"id",UUID.randomUUID().toString(),"v",body.get("version"),"mastery",body.get("mastery"),"wrong",body.get("isWrong"),"note",body.get("note"));long count=r.db.queryForObject("SELECT COUNT(*) FROM question_progress WHERE user_id=:u AND question_id=:q",p,Long.class);
        if(count==0){version(0,body.get("version"));r.db.update("INSERT INTO question_progress(id,user_id,question_id,mastery,is_wrong,note) VALUES(:id,:u,:q,:mastery,:wrong,:note)",p);}else {version(questionProgress(u,id).get("version"),body.get("version"));r.db.update("UPDATE question_progress SET mastery=:mastery,is_wrong=:wrong,note=:note,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND question_id=:q AND version=:v",p);}return questionProgress(u,id);
    });}
    public Page experiences(String u,boolean mine,String q,String company,String role,String round,int page,int size){paging(page,size);q=query(q);var p=map("u",u,"q",q,"company",company,"role",role,"round",round,"size",size,"offset",(page-1)*size);String where=mine?" WHERE author_id=:u AND status<>'HIDDEN'":" WHERE status='PUBLISHED'";if(!q.isEmpty())where+=" AND MATCH(title,body_md) AGAINST (:q IN NATURAL LANGUAGE MODE)";if(company!=null&&!company.isBlank())where+=" AND company_id=:company";if(role!=null&&!role.isBlank())where+=" AND role=:role";if(round!=null&&!round.isBlank())where+=" AND round_type=:round";return new Page(r.query("SELECT "+EXP+" FROM experiences"+where+" ORDER BY updated_at DESC,id LIMIT :size OFFSET :offset",p,TAGS,Set.of()),r.db.queryForObject("SELECT COUNT(*) FROM experiences"+where,p,Long.class));}
    public Map<String,Object> experience(String u,String id){return r.one("SELECT "+EXP+" FROM experiences WHERE id=:id AND (status='PUBLISHED' OR author_id=:u)",map("id",id,"u",u),TAGS,Set.of());}
    private Map<String,Object> ownedExperience(String u,String id){return r.one("SELECT "+EXP+" FROM experiences WHERE id=:id AND author_id=:u",map("id",id,"u",u),TAGS,Set.of());}
    public Object createExperience(String u,String key,Map<String,Object> body){inputs.validate("ExperienceInput",body);return tx.write(u,"POST","/experiences",key,body,201,false,()->{String id=UUID.randomUUID().toString();var p=map("id",id,"u",u);p.putAll(body);p.put("tags",r.json.writeValueAsString(body.get("tags")));if(body.get("companyId")!=null)company(body.get("companyId").toString());r.db.update("INSERT INTO experiences(id,author_id,company_id,title,summary,body_md,role,round_type,occurred_on,tags,content_mode,license_note,status) VALUES(:id,:u,:companyId,:title,:summary,:bodyMd,:role,:roundType,:occurredOn,:tags,'ORIGINAL','作者原创','DRAFT')",p);return experience(u,id);});}
    public Object patchExperience(String u,String id,Map<String,Object> body){inputs.validate("ExperiencePatch",body);return tx.write(u,"PATCH","/experiences/"+id,null,body,200,false,()->{var old=ownedExperience(u,id);version(old.get("version"),body.get("version"));if(body.get("companyId")!=null)company(body.get("companyId").toString());var p=map("id",id,"u",u,"v",body.get("version"));var sets=new StringBuilder("status='DRAFT',version=version+1,updated_at=CURRENT_TIMESTAMP");int i=0;for(var e:body.entrySet()){if(e.getKey().equals("version"))continue;String column=SqlRows.snake(e.getKey());String param="p"+i++;sets.append(',').append(column).append("=:").append(param);p.put(param,column.equals("tags")?r.json.writeValueAsString(e.getValue()):e.getValue());}r.db.update("UPDATE experiences SET "+sets+" WHERE id=:id AND author_id=:u AND version=:v",p);return experience(u,id);});}
    public Object submitExperience(String u,String id,Map<String,Object> body){inputs.validate("VersionInput",body);return tx.write(u,"POST","/experiences/"+id+"/submit",null,body,200,false,()->{var old=ownedExperience(u,id);version(old.get("version"),body.get("version"));if(!Set.of("DRAFT","REJECTED").contains(old.get("status")))throw new ApiProblem(409,"INVALID_STATE","当前状态不能提交审核。");r.db.update("UPDATE experiences SET status='PENDING',version=version+1 WHERE id=:id AND author_id=:u",map("id",id,"u",u));return experience(u,id);});}
    public void deleteExperience(String u,String id,int v){tx.write(u,"DELETE","/experiences/"+id,null,Map.of("version",v),204,false,()->{version(ownedExperience(u,id).get("version"),v);r.db.update("UPDATE experiences SET status='HIDDEN',version=version+1 WHERE id=:id AND author_id=:u",map("id",id,"u",u));return null;});}
    public Map<String,Object> pack(String slug){var c=companyBySlug(slug);String id=c.get("id").toString();var questions=questions(null,null,null,id,1,50).data();var chapterIds=new HashSet<String>();for(var q:questions)if(q.get("chapterId")!=null)chapterIds.add(q.get("chapterId").toString());var chapters=new ArrayList<Map<String,Object>>();for(String cid:chapterIds)if(chapters.size()<30){try{chapters.add(published("chapters",CHAPTER,cid,Set.of()));}catch(ApiProblem ignored){}}return map("companyId",id,"experiences",experiences(null,false,null,id,null,null,1,50).data(),"questions",questions,"chapters",chapters);}
    public Map<String,Object> style(String slug){var c=companyBySlug(slug);String id=c.get("id").toString();var rounds=r.query("SELECT round_type,COUNT(*) count FROM experiences WHERE company_id=:id AND status='PUBLISHED' AND created_at>=:since GROUP BY round_type ORDER BY count DESC,round_type LIMIT 20",map("id",id,"since",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(365L*86400))));long samples=r.db.queryForObject("SELECT COUNT(*) FROM experiences WHERE company_id=:id AND status='PUBLISHED' AND created_at>=:since",map("id",id,"since",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(365L*86400))),Long.class);return map("companyId",id,"sampleSize",samples,"windowStart",java.time.LocalDate.now(java.time.ZoneOffset.UTC).minusDays(365).toString(),"windowEnd",java.time.LocalDate.now(java.time.ZoneOffset.UTC).toString(),"rounds",rounds,"tags",List.of(),"limitations",List.of("基于最近365天已发布面经记录，不代表公司官方标准。","缺少发生日期的记录按录入时间统计。"));}
}
